import sys

def keccak_f(state):
    RC = [0x0000000000000001,0x0000000000008082,0x800000000000808A,0x8000000080008000,
          0x000000000000808B,0x0000000080000001,0x8000000080008081,0x8000000000008009,
          0x000000000000008A,0x0000000000000088,0x0000000080008009,0x000000008000000A,
          0x000000008000808B,0x800000000000008B,0x8000000000008089,0x8000000000008003,
          0x8000000000008002,0x8000000000000080,0x000000000000800A,0x800000008000000A,
          0x8000000080008081,0x8000000000008080,0x0000000080000001,0x8000000080008008]
    R = [[0,36,3,41,18],[1,44,10,45,2],[62,6,43,15,61],[28,55,25,21,56],[27,20,39,8,14]]
    def rol(x,n):
        n %= 64
        return ((x<<n)|(x>>(64-n))) & 0xFFFFFFFFFFFFFFFF
    A = [[state[x+5*y] for y in range(5)] for x in range(5)]
    for rnd in range(24):
        C = [A[x][0]^A[x][1]^A[x][2]^A[x][3]^A[x][4] for x in range(5)]
        D = [C[(x-1)%5]^rol(C[(x+1)%5],1) for x in range(5)]
        for x in range(5):
            for y in range(5):
                A[x][y] ^= D[x]
        B = [[0]*5 for _ in range(5)]
        for x in range(5):
            for y in range(5):
                B[y][(2*x+3*y)%5] = rol(A[x][y], R[x][y])
        for x in range(5):
            for y in range(5):
                A[x][y] = B[x][y] ^ ((~B[(x+1)%5][y]) & B[(x+2)%5][y]) & 0xFFFFFFFFFFFFFFFF
        A[0][0] ^= RC[rnd]
    out = [0]*25
    for x in range(5):
        for y in range(5):
            out[x+5*y] = A[x][y]
    return out

def keccak256(data):
    rate = 136
    state = [0]*25
    # padding: append 0x01, then zeros, then 0x80 at last byte of block (Keccak original)
    padded = bytearray(data)
    padded.append(0x01)
    while len(padded) % rate != 0:
        padded.append(0)
    padded[-1] |= 0x80
    for i in range(0, len(padded), rate):
        block = padded[i:i+rate]
        for j in range(rate//8):
            lane = int.from_bytes(block[j*8:(j+1)*8], 'little')
            state[j] ^= lane
        state = keccak_f(state)
    out = bytearray()
    for j in range(rate//8):
        out += state[j].to_bytes(8, 'little')
        if len(out) >= 32:
            break
    return bytes(out[:32])

def eth_address(pubkey_hex):
    pub = bytes.fromhex(pubkey_hex.strip())
    h = keccak256(pub)
    addr = h[-20:].hex()
    hh = keccak256(addr.encode()).hex()
    out = '0x'
    for i, c in enumerate(addr):
        if c in '0123456789':
            out += c
        else:
            out += c.upper() if int(hh[i], 16) >= 8 else c
    return out

def main():
    data = sys.stdin.read().strip()
    print(eth_address(data))

main()
